import{z as i,x as u,o as t,c as n,q as c,j as p,D as o,d as e,s as E,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"cgroup CPU 组调度","description":"","frontmatter":{"title":"cgroup CPU 组调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cgroup-cpu-sched.md","filePath":"cs/cgroup-cpu-sched.md","lastUpdated":1791063341000}'),d={name:"cs/cgroup-cpu-sched.md"};function B(A,a,h,m,C,g){const s=u("Mermaid");return t(),n("div",null,[a[2]||(a[2]=c('<h1 id="cgroup-cpu-组调度" tabindex="-1">cgroup CPU 组调度 <a class="header-anchor" href="#cgroup-cpu-组调度" aria-label="Permalink to &quot;cgroup CPU 组调度&quot;">​</a></h1><div class="epigraph"><p>cpu 控制器把一组任务当成可加权的实体：组有 vruntime/份额，组内再分，使容器不能靠多线程骗走整机 CPU。</p><footer>—— 据 Linux cgroup v2 cpu 文档；内核 CFS 组调度说明</footer></div><p><a href="/cs/latency-measurement">上一课</a>留下的缺口接到本课。 <a href="/cs/memcg">memcg</a>/<a href="/cs/blkio-cgroup">blkio</a> 已限内存与 I/O。<a href="/cs/eevdf">EEVDF</a> 的任务是叶。缺口是 <strong>组调度</strong>：<code>cpu.weight</code>/<code>cpu.max</code> 如何进 runqueue。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>十个线程 nice 0 会比一个线程多吃 CPU。组：容器整体权重 100，内部再抢。缺口：带宽 <code>cpu.max</code> 配额（quota/period）把组变成 DL 式的上限；实时任务是否进 cpu 控制器（配置而定）。本课不把 v1 cpu.shares 与 v2 weight 的换算表当正文。</p><p><span class="marginnote">术语翻译：组调度就是把「一组进程」当一个调度对象——调度器先在组之间按权重分 CPU，再在组内部分给具体线程。没有它，容器里塞 100 个线程就能在 nice 相同的规则下抢走单线程租户 100 倍的份额。</span></p><p><span class="marginnote">层次化：父组限额约束子组。空闲组不积欠无限（实现有 clamp）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入队：任务挂到组实体，组实体挂到 CPU 的根。选择：先选组再选任务。对照 <a href="/cs/blk-schedulers">BFQ</a> 的 cgroup 权重。对照 <a href="/cs/socket-buffers">net</a>：网络另有控制器。对照 DEADLINE：cpu.max 是 CFS 组的限额，不是 SCHED_DEADLINE 本身。</p>',9)),(t(),p(l,null,{default:o(()=>[E(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20G%5B%22%E7%BB%84%E8%B0%83%E5%BA%A6%E5%AE%9E%E4%BD%93%22%5D%0A%20%20G%20--%3E%20RQ%5B%22CPU%20runqueue%22%5D%0A%20%20W%5B%22cpu.weight%22%5D%20--%3E%20G%0A%20%20M%5B%22cpu.max%22%5D%20--%3E%20THR%5B%22%E9%85%8D%E9%A2%9D%E7%94%A8%E5%B0%BD%E5%88%99%E8%8A%82%E6%B5%81%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("组调度把「容器是一个用户」收成调度实体，使多租户 CPU 公平不依赖线程数。它不提供硬实时除非配合 DL/RT 配置。不要写成云规格账单。与 "),r("a",{href:"/cs/eas-scheduling"},"EAS"),e("：组 util 影响选核。")],-1)),a[5]||(a[5]=r("p",null,"配额用尽时组内全部 CFS 任务睡到下周期，看起来像卡顿。",-1)),(t(),p(l,null,{default:o(()=>[E(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20P0%5B%22%E5%91%A8%E6%9C%9F%E5%BC%80%E5%A7%8B%EF%BC%9A%E9%85%8D%E9%A2%9D%E5%85%85%E5%80%BC%20quota%22%5D%20--%3E%20RUN%5B%22%E7%BB%84%E5%86%85%E4%BB%BB%E5%8A%A1%E8%BF%90%E8%A1%8C%E6%89%A3%E6%97%B6%22%5D%0A%20%20RUN%20--%3E%20LEFT%7B%22%E6%9C%AC%E5%91%A8%E6%9C%9F%E5%89%A9%E4%BD%99%E9%85%8D%E9%A2%9D%20%EF%BC%9E%200%EF%BC%9F%22%7D%0A%20%20LEFT%20--%3E%7C%22%E6%98%AF%22%7C%20RUN%0A%20%20LEFT%20--%3E%7C%22%E5%90%A6%22%7C%20THR%5B%22%E6%95%B4%E7%BB%84%E8%8A%82%E6%B5%81%EF%BC%9A%E4%BB%BB%E5%8A%A1%E7%9D%A1%E5%88%B0%E4%B8%8B%E5%91%A8%E6%9C%9F%22%5D%0A%20%20THR%20--%3E%20NEXT%5B%22%E6%96%B0%E5%91%A8%E6%9C%9F%EF%BC%9A%E9%85%8D%E9%A2%9D%E9%87%8D%E6%96%B0%E5%8F%AF%E7%94%A8%22%5D%0A%20%20NEXT%20--%3E%20RUN%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=c('<p><span class="marginnote">数字实例：<code>cpu.max</code> 写成「50000 100000」意思是每 100000 微秒（100 毫秒）的周期里最多跑 50000 微秒——折合半个核。写「200000 100000」就是 2 个核。配额是按墙钟时间扣的，多线程并不能突破这个总额。</span></p><p><span class="marginnote">常见误区：容器监控上周期性的卡顿尖刺，常被误诊为「机器慢」或「负载突增」——真实原因往往是配额用尽后整组任务被冻结到下个周期（节流），表现为每 100 毫秒一次的停顿。查 cgroup 的 throttled 统计比换机器有效。</span></p><p>实现上：层次化份额是相对的，父组限额会切子组。cpu.max 用完后组内 CFS 全部睡到下个 period。实时任务是否受 cpu 控制器管取决于配置。 读法上只引用<a href="/cs/latency-measurement">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>cgroup CPU 组调度</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cpu.idle 的全部。不保证与 cpuset 的每个交叉。下一课可编程调度器：sched_ext。</p><p>版本字段会变，课序钉的是机制对象「cgroup CPU 组调度」，不是某一主线内核的结构体名。 后课默认：CFS/EEVDF 可按 cgroup 加权与限额。用 BPF 写调度器，下一课 sched_ext。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cpu 控制器让组成为调度实体。</li><li>weight 摊份额，max 封顶。</li><li>sched_ext 是下一课。</li><li>出处：cgroup v2 cpu；Linux 组调度。</li></ul>',10))])}const _=i(d,[["render",B]]);export{f as __pageData,_ as default};
